function loadCKEditor(callback: () => void) {
    if ((window as any).ClassicEditor) {
        callback();
        return;
    }

    const script = document.createElement("script");
    script.src = "https://cdn.ckeditor.com/ckeditor5/41.0.0/classic/ckeditor.js";
    script.onload = callback;
    document.head.appendChild(script);
}

loadCKEditor(async () => {
    const node = getNode(nodeId);
    let currentLang = "en"; // par défaut
    if (node.language_id === 1) currentLang = "fr"; // exemple

    const modalDiv = document.createElement("div");
    modalDiv.style.cssText = `
        display: flex;
        flex-direction: column;
        gap: 16px;
    `;

    // --- Sélecteur de langue ---
    const langDiv = document.createElement("div");
    langDiv.innerHTML = `
        <label><input type="radio" name="lang" value="fr" ${currentLang === "fr" ? "checked" : ""}> FR</label>
        <label><input type="radio" name="lang" value="en" ${currentLang === "en" ? "checked" : ""}> EN</label>
    `;
    modalDiv.appendChild(langDiv);

    // --- Zones CKEditor ---
    const titleDiv = document.createElement("textarea");
    const descDiv = document.createElement("textarea");

    modalDiv.appendChild(titleDiv);
    modalDiv.appendChild(descDiv);

    let titleEditor: any = null;
    let descEditor: any = null;

    function initEditor(textarea: HTMLTextAreaElement, key: string) {
        (window as any).ClassicEditor
            .create(textarea)
            .then((editor: any) => {
                editor.model.document.on("change:data", () => {
                    const newNode = { ...getNode(nodeId) };
                    if (!newNode.data) newNode.data = {};
                    if (!newNode.data[currentLang]) newNode.data[currentLang] = {};
                    newNode.data[currentLang][key] = editor.getData();
                    updateNode(newNode);
                });
                // initialisation
                const initNode = getNode(nodeId);
                if (initNode.data?.[currentLang]?.[key]) {
                    editor.setData(initNode.data[currentLang][key]);
                }
                if (key === "title") titleEditor = editor;
                else descEditor = editor;
            })
            .catch((err: any) => console.error("CKEditor error:", err));
    }

    initEditor(titleDiv, "title");
    initEditor(descDiv, "description");

    // --- Changement de langue ---
    const radios = langDiv.querySelectorAll<HTMLInputElement>('input[name="lang"]');
    radios.forEach(radio => {
        radio.onclick = () => {
            currentLang = radio.value;
            const contentNode = getNode(nodeId).data?.[currentLang] || {};
            if (titleEditor) titleEditor.setData(contentNode.title || "");
            if (descEditor) descEditor.setData(contentNode.description || "");
        };
    });

    // --- Ouvrir modal ---
    const id = await modalManager.open({
        id: "form-editor",
        title: "Edit Form",
        content: modalDiv,
        width: "600px",
        height: "400px",
        nodeId: nodeId,
        onClose: () => {
            if (titleEditor) titleEditor.destroy();
            if (descEditor) descEditor.destroy();
        }
    });
});

