    let titleEditor = null;
    let descEditor = null;

    // Garde tous les éditeurs de questions et réponses
    const questionEditors = []; // { questionEditor, responseEditors: [] }

    const container = document.createElement("div");
    container.style.cssText = "display:flex; flex-direction:column; gap:16px;";

    /* ---------------- LANGUAGE SELECTOR ---------------- */
    const langDiv = document.createElement("div");
    langDiv.innerHTML = `
        <label><input type="radio" name="lang" value="fr"> FR</label>
        <label><input type="radio" name="lang" value="en" checked> EN</label>
    `;
    container.appendChild(langDiv);

    /* ---------------- FORM TITLE ---------------- */
    const titleLabel = document.createElement("div");
    titleLabel.textContent = "Form Title";
    titleLabel.style.fontWeight = "600";
    container.appendChild(titleLabel);

    const titleTextarea = document.createElement("textarea");
    container.appendChild(titleTextarea);

    /* ---------------- FORM DESCRIPTION ---------------- */
    const descLabel = document.createElement("div");
    descLabel.textContent = "Form Description";
    descLabel.style.fontWeight = "600";
    container.appendChild(descLabel);

    const descTextarea = document.createElement("textarea");
    container.appendChild(descTextarea);

    /* ---------------- FORM QUESTIONS ---------------- */
    const questionsLabel = document.createElement("div");
    questionsLabel.textContent = "Forms questions";
    questionsLabel.style.fontWeight = "600";
    questionsLabel.style.marginTop = "16px";
    container.appendChild(questionsLabel);

    const questionsList = document.createElement("div");
    questionsList.style.cssText = "display:flex; flex-direction:column; gap:12px;";
    container.appendChild(questionsList);

    const addQuestionBtn = document.createElement("button");
    addQuestionBtn.textContent = "+ Add question";
    addQuestionBtn.style.cssText = "width:fit-content; padding:6px 12px; cursor:pointer;";
    container.appendChild(addQuestionBtn);

    /* ---------------- HELPERS ---------------- */
    function ensureData() {
        const n = getNode(nodeId);
        if (!n.data) n.data = {};
        if (!n.data[currentLang]) n.data[currentLang] = {};
        if (!n.data[currentLang].questions) n.data[currentLang].questions = [];
        return n;
    }

    function destroyEditors() {
        // détruit tous les CKEditor questions + réponses
        questionEditors.forEach(q => {
            if (q.questionEditor) q.questionEditor.destroy().catch(() => {});
            q.responseEditors.forEach(r => r.destroy().catch(() => {}));
        });
        questionEditors.length = 0;
    }

    function renderQuestions() {
        destroyEditors();
        questionsList.innerHTML = "";

        const n = ensureData();
        n.data[currentLang].questions.forEach((q, qIndex) => {
            const wrapper = document.createElement("div");
            wrapper.style.cssText = `
                border:1px solid #ddd;
                padding:8px;
                border-radius:4px;
                position:relative;
            `;
            questionsList.appendChild(wrapper);

            // DELETE QUESTION BUTTON
            const deleteBtn = document.createElement("button");
            deleteBtn.textContent = "🗑";
            deleteBtn.title = "Delete question";
            deleteBtn.style.cssText = `
                position:absolute;
                top:6px;
                right:6px;
                cursor:pointer;
                background:none;
                border:none;
                font-size:16px;
            `;
            deleteBtn.onclick = () => {
                n.data[currentLang].questions.splice(qIndex, 1);
                updateNode(n);
                renderQuestions();
            };
            wrapper.appendChild(deleteBtn);

            // QUESTION EDITOR
            const questionTextarea = document.createElement("textarea");
            wrapper.appendChild(questionTextarea);

            const questionEditorData = { questionEditor: null, responseEditors: [] };
            ClassicEditor.create(questionTextarea).then(editor => {
                questionEditorData.questionEditor = editor;
                editor.model.document.on("change:data", () => {
                    const n = ensureData();
                    n.data[currentLang].questions[qIndex].label = editor.getData();
                    updateNode(n);
                });
                editor.setData(q.label || "");
            });

            // RESPONSES LIST
            const responsesList = document.createElement("div");
            responsesList.style.cssText = "display:flex; flex-direction:column; gap:8px; margin-top:8px;";
            wrapper.appendChild(responsesList);

            const addResponseBtn = document.createElement("button");
            addResponseBtn.textContent = "+ Add response";
            addResponseBtn.style.cssText = "width:fit-content; padding:4px 8px; cursor:pointer; margin-top:4px;";
            wrapper.appendChild(addResponseBtn);

            function renderResponses() {
                responsesList.innerHTML = "";
                questionEditorData.responseEditors.forEach(r => r.destroy().catch(() => {}));
                questionEditorData.responseEditors.length = 0;

                const n = ensureData();
                const responses = n.data[currentLang].questions[qIndex].responses || [];
                responses.forEach((r, rIndex) => {
                    const rWrapper = document.createElement("div");
                    rWrapper.style.cssText = "display:flex; align-items:center; gap:8px;";
                    responsesList.appendChild(rWrapper);

                    const checkbox = document.createElement("input");
                    checkbox.type = "checkbox";
                    checkbox.checked = r.correct || false;
                    checkbox.onchange = () => {
                        const n = ensureData();
                        n.data[currentLang].questions[qIndex].responses[rIndex].correct = checkbox.checked;
                        updateNode(n);
                    };
                    rWrapper.appendChild(checkbox);

                    const responseTextarea = document.createElement("textarea");
                    responseTextarea.style.cssText = "flex:1;";
                    rWrapper.appendChild(responseTextarea);

                    ClassicEditor.create(responseTextarea).then(rEditor => {
                        questionEditorData.responseEditors.push(rEditor);
                        rEditor.model.document.on("change:data", () => {
                            const n = ensureData();
                            n.data[currentLang].questions[qIndex].responses[rIndex].label = rEditor.getData();
                            updateNode(n);
                        });
                        rEditor.setData(r.label || "");
                    });

                    const deleteRBtn = document.createElement("button");
                    deleteRBtn.textContent = "🗑";
                    deleteRBtn.style.cssText = "background:none;border:none;cursor:pointer;font-size:14px;";
                    deleteRBtn.onclick = () => {
                        const n = ensureData();
                        n.data[currentLang].questions[qIndex].responses.splice(rIndex, 1);
                        updateNode(n);
                        renderQuestions(); // reload tout pour apparaitre
                    };
                    rWrapper.appendChild(deleteRBtn);
                });
            }

            addResponseBtn.onclick = () => {
                const n = ensureData();
                if (!n.data[currentLang].questions[qIndex].responses) {
                    n.data[currentLang].questions[qIndex].responses = [];
                }
                n.data[currentLang].questions[qIndex].responses.push({ label: "", correct: false });
                updateNode(n);
                renderQuestions(); // apparait immédiatement
            };

            questionEditors.push(questionEditorData);
            renderResponses();
        });
    }

    addQuestionBtn.onclick = () => {
        const n = ensureData();
        n.data[currentLang].questions.push({ id: Date.now().toString(), label: "", responses: [] });
        updateNode(n);
        renderQuestions(); // reload direct
    };

    /* ---------------- INIT CKEDITOR TITLE/DESC ---------------- */
    titleEditor = await ClassicEditor.create(titleTextarea);
    titleEditor.model.document.on("change:data", () => {
        const n = ensureData();
        n.data[currentLang].title = titleEditor.getData();
        updateNode(n);
    });

    descEditor = await ClassicEditor.create(descTextarea);
    descEditor.model.document.on("change:data", () => {
        const n = ensureData();
        n.data[currentLang].description = descEditor.getData();
        updateNode(n);
    });

    /* ---------------- LANGUAGE SWITCH ---------------- */
    langDiv.querySelectorAll("input[name='lang']").forEach(radio => {
        radio.onclick = () => {
            currentLang = radio.value;
            const n = ensureData();
            if (titleEditor) titleEditor.setData(n.data[currentLang].title || "");
            if (descEditor) descEditor.setData(n.data[currentLang].description || "");
            renderQuestions();
        };
    });

    renderQuestions();

    /* ---------------- OPEN MODAL ---------------- */
    modalManager.open({
        id: "form-editor",
        title: "Edit Form",
        content: container,
        width: "800px",
        height: "650px",
        nodeId: nodeId,
        onClose: () => {
            titleEditor.destroy().catch(() => {});
            descEditor.destroy().catch(() => {});
            destroyEditors();
        }
    });
});

