        questionEditors.forEach(q => {
            if (q.questionEditor) q.questionEditor.destroy().catch(() => {});
            q.responseEditors.forEach(r => r.destroy().catch(() => {}));
        });
        questionEditors.length = 0;
    }

    function renderQuestions() {
