        title: "Edit Form",
        content: container,
        width: "800px",
        height: "650px",
        nodeId: nodeId,
        onClose: () => {
            titleEditor.destroy().catch(() => {});
            descEditor.destroy().catch(() => {});
            destroyEditors();
        }
    });
});

