            rDeleteBtn.onclick = function(){
                var n = ensureData();
                n.data[currentLang].questions[qIndex].responses.splice(rIndex,1);
                updateNode(n);
                responsesList.removeChild(rWrapper);
                reindexResponses(qIndex);
