        // Recompute question numbers after deletion
        Array.from(questionsList.children).forEach((wrapper, idx) => {
            var headerTitle = wrapper.querySelector("div:first-child div");
            if (headerTitle) headerTitle.textContent = `Question ${idx + 1}`;
        });
    }

