        titleEditor = editor;
        var n = ensureData();
        editor.setData(n.data[currentLang].title || "");
        editor.model.document.on("change:data", function () {
            var n = ensureData();
            n.data[currentLang].title = editor.getData();
            updateNode(n);
        });
    });

    ClassicEditor.create(descTextarea).then(function (editor) {
        descEditor = editor;
        var n = ensureData();
        editor.setData(n.data[currentLang].description || "");
        editor.model.document.on("change:data", function () {
            var n = ensureData();
            n.data[currentLang].description = editor.getData();
            updateNode(n);
        });
    });

    /* ---------------- LANGUAGE SWITCH ---------------- */
    langDiv.querySelectorAll("input[name='lang']").forEach(function(radio) {
        radio.onclick = function() {
            currentLang = radio.value;
            var n = ensureData();

            if (titleEditor) titleEditor.setData(n.data[currentLang].title || "");
            if (descEditor) descEditor.setData(n.data[currentLang].description || "");

            // Clear questions and re-render
            questionsList.innerHTML = "";
            questionEditors = [];
            responseEditors = [];
            n.data[currentLang].questions.forEach((q, qIndex) => renderSingleQuestion(q, qIndex));
        };
    });

    // Initial render
    var n = ensureData();
    n.data[currentLang].questions.forEach((q, qIndex) => renderSingleQuestion(q, qIndex));

    /* ---------------- OPEN MODAL ---------------- */
    modalManager.open({
        id: "form-editor",
        title: "Edit Form",
        content: container,
        width: "900px",
        height: "700px",
        nodeId: nodeId,
        onClose: function () {
            if (titleEditor) titleEditor.destroy();
            if (descEditor) descEditor.destroy();
            questionEditors.forEach(e=>{try{e.editor.destroy();}catch(e){}} );
            responseEditors.forEach(e=>{try{e.editor.destroy();}catch(e){}} );
        }
    });
});

