        title: "Edit Form",
        content: container,
        width: "900px",
        height: "700px",
        nodeId: nodeId,
        onClose: function () {
            if(titleEditor) titleEditor.destroy();
            if(descEditor) descEditor.destroy();
            questionEditors.forEach(ed=>ed.destroy());
        }
    });

