        const n = getNode(nodeId);
        if (!n.data) n.data = {};
        if (!n.data[currentLang]) n.data[currentLang] = {};
        if (!("questions" in n.data[currentLang])) n.data[currentLang].questions = [];
        if (!("title" in n.data[currentLang])) n.data[currentLang].title = "";
        if (!("description" in n.data[currentLang])) n.data[currentLang].description = "";
        return n;
    }

    function findQuestionById(qId) {
        const n = ensureData();
        return n.data[currentLang].questions.find(q => q.id === qId);
    }

    /* ---------------- CREATE RESPONSE ---------------- */
    function createResponse(q, resp, responseEditors) {
        const rWrapper = document.createElement("div");
        rWrapper.style.cssText = "display:flex; align-items:center; gap:6px;";

        const checkbox = document.createElement("input");
        checkbox.type = "checkbox";
        checkbox.checked = resp.checked || false;
        rWrapper.appendChild(checkbox);

        const rTextarea = document.createElement("textarea");
        rTextarea.style.width = "100%";
        rWrapper.appendChild(rTextarea);

        const rDeleteBtn = document.createElement("button");
        rDeleteBtn.textContent = "🗑";
        rDeleteBtn.style.cssText = "cursor:pointer; background:none; border:none; color:#c00;";
        rWrapper.appendChild(rDeleteBtn);

        rDeleteBtn.onclick = function () {
            const qData = findQuestionById(q.id);
            qData.responses = qData.responses.filter(r => r !== resp);
            updateNode(ensureData());
            rWrapper.remove();

            // détruit l'éditeur associé
            const idx = responseEditors.findIndex(e => e.responseObj === resp);
            if (idx >= 0) {
                responseEditors[idx].editor.destroy();
                responseEditors.splice(idx, 1);
            }
        };

        ClassicEditor.create(rTextarea).then(editor => {
            editor.model.document.on("change:data", function () {
                resp.label = editor.getData();
                updateNode(ensureData());
            });
            editor.setData(resp.label || "");
            responseEditors.push({ editor, responseObj: resp });
        });

        checkbox.onchange = function () {
            resp.checked = checkbox.checked;
            updateNode(ensureData());
        };

        return rWrapper;
    }

    /* ---------------- CREATE QUESTION ---------------- */
    function createQuestion(q) {
        const n = ensureData();
        if (!q.responses) q.responses = [];

        const wrapper = document.createElement("div");
        wrapper.style.cssText = `
            border:1px solid #ddd;
            padding:8px;
            border-radius:4px;
            display:flex;
            flex-direction:column;
            gap:6px;
        `;
        questionsList.appendChild(wrapper);

        const header = document.createElement("div");
        header.style.cssText = "display:flex; justify-content:space-between; align-items:center;";
        wrapper.appendChild(header);

        const headerTitle = document.createElement("div");
        headerTitle.textContent = `Question ${questionsList.children.length}`;
        headerTitle.style.fontWeight = "600";
        header.appendChild(headerTitle);

        const deleteBtn = document.createElement("button");
        deleteBtn.textContent = "🗑 Delete";
        deleteBtn.style.cssText = "cursor:pointer; background:none; border:none; color:#c00; font-size:14px;";
        header.appendChild(deleteBtn);

        const textarea = document.createElement("textarea");
        wrapper.appendChild(textarea);

        const responseEditors = [];

        ClassicEditor.create(textarea).then(editor => {
            editor.model.document.on("change:data", function () {
                const qData = findQuestionById(q.id);
                if (qData) qData.label = editor.getData();
                updateNode(ensureData());
            });
            editor.setData(q.label || "");
            questionEditors.push({ questionId: q.id, editor, responseEditors });
        });

        const responsesList = document.createElement("div");
        responsesList.style.cssText = "display:flex; flex-direction:column; gap:4px; margin-left:20px;";
        wrapper.appendChild(responsesList);

        q.responses.forEach(resp => {
            const rWrapper = createResponse(q, resp, responseEditors);
            responsesList.appendChild(rWrapper);
        });

        const addRespBtn = document.createElement("button");
        addRespBtn.textContent = "+ Add Response";
        addRespBtn.style.cssText = "width:fit-content; padding:4px 8px; cursor:pointer; margin-left:20px;";
        wrapper.appendChild(addRespBtn);

        addRespBtn.onclick = function () {
            const newResp = { label: "", checked: false };
            q.responses.push(newResp);
            const rWrapper = createResponse(q, newResp, responseEditors);
            responsesList.appendChild(rWrapper);
            updateNode(ensureData());
        };

        deleteBtn.onclick = function () {
            const n2 = ensureData();
            n2.data[currentLang].questions = n2.data[currentLang].questions.filter(qq => qq.id !== q.id);
            updateNode(n2);
            wrapper.remove();

            const idx = questionEditors.findIndex(qe => qe.questionId === q.id);
            if (idx >= 0) {
                questionEditors[idx].editor.destroy();
                questionEditors[idx].responseEditors.forEach(e => e.editor.destroy());
                questionEditors.splice(idx, 1);
            }

            // mise à jour numérotation
            Array.from(questionsList.children).forEach((child, idx) => {
                child.querySelector("div").textContent = `Question ${idx + 1}`;
            });
        };
    }

    /* ---------------- ADD QUESTION ---------------- */
    addQuestionBtn.onclick = function () {
        const n = ensureData();
        const newQ = { id: Date.now().toString(), label: "", responses: [] };
        n.data[currentLang].questions.push(newQ);
        updateNode(n);
        createQuestion(newQ);
    };

    /* ---------------- INIT TITLE & DESCRIPTION ---------------- */
    ClassicEditor.create(titleTextarea).then(editor => {
        titleEditor = editor;
        const n = ensureData();
        editor.setData(n.data[currentLang].title || "");
        editor.model.document.on("change:data", function () {
            const n2 = ensureData();
            n2.data[currentLang].title = editor.getData();
            updateNode(n2);
        });
    });

    ClassicEditor.create(descTextarea).then(editor => {
        descEditor = editor;
        const n = ensureData();
        editor.setData(n.data[currentLang].description || "");
        editor.model.document.on("change:data", function () {
            const n2 = ensureData();
            n2.data[currentLang].description = editor.getData();
            updateNode(n2);
        });
    });

    /* ---------------- LANGUAGE SWITCH ---------------- */
    langDiv.querySelectorAll("input[name='lang']").forEach(radio => {
        radio.onclick = function () {
            currentLang = radio.value;
            const n = ensureData();
            if (titleEditor) titleEditor.setData(n.data[currentLang].title || "");
            if (descEditor) descEditor.setData(n.data[currentLang].description || "");

            // détruit tous les éditeurs existants
            questionEditors.forEach(qe => {
                qe.editor.destroy();
                qe.responseEditors.forEach(e => e.editor.destroy());
            });
            questionEditors = [];

            // recharge toutes les questions
            questionsList.innerHTML = "";
            n.data[currentLang].questions.forEach(q => createQuestion(q));
        };
    });

    /* ---------------- OPEN MODAL ---------------- */
    modalManager.open({
        id: "form-editor",
        title: "Edit Form",
        content: container,
        width: "900px",
        height: "700px",
        nodeId: nodeId,
        onClose: function () {
            if (titleEditor) titleEditor.destroy();
            if (descEditor) descEditor.destroy();
            questionEditors.forEach(qe => {
                qe.editor.destroy();
                qe.responseEditors.forEach(e => e.editor.destroy());
            });
        }
    });

    // Load existing questions
    const n = ensureData();
    n.data[currentLang].questions.forEach(q => createQuestion(q));
});

