function loadCKEditor(callback) {
    if (window.ClassicEditor) {
        callback();
        return;
    }
    var script = document.createElement("script");
    script.src = "https://cdn.ckeditor.com/ckeditor5/41.0.0/classic/ckeditor.js";
    script.onload = callback;
    document.head.appendChild(script);
}

loadCKEditor(function () {

    var currentLang = "en";
    var titleEditor = null;
    var descEditor = null;
    var questionEditors = [];
    var responseEditors = []; // tableau global pour CKEditor des réponses

    var container = document.createElement("div");
    container.style.cssText = "display:flex; flex-direction:column; gap:16px;";

    /* ---------------- LANGUAGE SELECTOR ---------------- */
    var langDiv = document.createElement("div");
    langDiv.innerHTML = `
        <label><input type="radio" name="lang" value="fr"> FR</label>
        <label><input type="radio" name="lang" value="en" checked> EN</label>
    `;
    container.appendChild(langDiv);

    /* ---------------- FORM TITLE ---------------- */
    var titleLabel = document.createElement("div");
    titleLabel.textContent = "Form Title";
    titleLabel.style.fontWeight = "600";
    container.appendChild(titleLabel);

    var titleTextarea = document.createElement("textarea");
    container.appendChild(titleTextarea);

    /* ---------------- FORM DESCRIPTION ---------------- */
    var descLabel = document.createElement("div");
    descLabel.textContent = "Form Description";
    descLabel.style.fontWeight = "600";
    container.appendChild(descLabel);

    var descTextarea = document.createElement("textarea");
    container.appendChild(descTextarea);

    /* ---------------- QUESTIONS ---------------- */
    var questionsLabel = document.createElement("div");
    questionsLabel.textContent = "Forms questions";
    questionsLabel.style.fontWeight = "600";
    questionsLabel.style.marginTop = "16px";
    container.appendChild(questionsLabel);

    var questionsList = document.createElement("div");
    questionsList.style.cssText = "display:flex; flex-direction:column; gap:12px;";
    container.appendChild(questionsList);

    var addQuestionBtn = document.createElement("button");
    addQuestionBtn.textContent = "+ Add question";
    addQuestionBtn.style.cssText = "width:fit-content; padding:6px 12px; cursor:pointer;";
    container.appendChild(addQuestionBtn);

    /* ---------------- DATA HELPERS ---------------- */
    function ensureData() {
        var n = getNode(nodeId);
        if (!n.data) n.data = {};
        if (!n.data[currentLang]) n.data[currentLang] = {};
        if (!("questions" in n.data[currentLang])) n.data[currentLang].questions = [];
        if (!("title" in n.data[currentLang])) n.data[currentLang].title = n.data[currentLang].title || "";
        if (!("description" in n.data[currentLang])) n.data[currentLang].description = n.data[currentLang].description || "";
        return n;
    }

    function destroyQuestionEditors() {
        questionEditors.forEach(function (ed) { try { ed.destroy(); } catch(e){} });
        questionEditors = [];
        responseEditors.forEach(function (ed) { try { ed.destroy(); } catch(e){} });
        responseEditors = [];
    }

    /* ---------------- RENDER QUESTIONS ---------------- */
    function renderQuestions() {
        destroyQuestionEditors();
        questionsList.innerHTML = "";

        var n = ensureData();

        n.data[currentLang].questions.forEach(function (q, qIndex) {

            if (!q.responses) q.responses = []; // initialise réponses si absent

            var wrapper = document.createElement("div");
            wrapper.style.cssText = `
                border:1px solid #ddd;
                padding:8px;
                border-radius:4px;
                display:flex;
                flex-direction:column;
                gap:6px;
            `;
            questionsList.appendChild(wrapper);

            /* HEADER */
            var header = document.createElement("div");
            header.style.cssText = "display:flex; justify-content:space-between; align-items:center;";
            wrapper.appendChild(header);

            // Question X
            var headerTitle = document.createElement("div");
            headerTitle.textContent = `Question ${qIndex + 1}`;
            headerTitle.style.fontWeight = "600";
            header.appendChild(headerTitle);

            /* DELETE QUESTION BUTTON */
            var deleteBtn = document.createElement("button");
            deleteBtn.textContent = "🗑 Delete";
            deleteBtn.style.cssText = "cursor:pointer; background:none; border:none; color:#c00; font-size:14px;";
            header.appendChild(deleteBtn);

            deleteBtn.onclick = function() {
                n.data[currentLang].questions.splice(qIndex, 1);
                updateNode(n);
                renderQuestions();
            };

            /* QUESTION CKEDITOR */
            var textarea = document.createElement("textarea");
            wrapper.appendChild(textarea);

            ClassicEditor.create(textarea).then(function (editor) {
                questionEditors.push(editor);
                editor.model.document.on("change:data", function () {
                    var n2 = ensureData();
                    n2.data[currentLang].questions[qIndex].label = editor.getData();
                    updateNode(n2);
                });
                editor.setData(q.label || "");
            });

            /* RESPONSES LIST */
            var responsesList = document.createElement("div");
            responsesList.style.cssText = "display:flex; flex-direction:column; gap:4px; margin-left:20px;";
            wrapper.appendChild(responsesList);

            function renderResponses() {
                responsesList.innerHTML = "";
                q.responses.forEach(function(resp, rIndex){
                    var rWrapper = document.createElement("div");
                    rWrapper.style.cssText = "display:flex; align-items:center; gap:6px;";

                    var checkbox = document.createElement("input");
                    checkbox.type = "checkbox";
                    checkbox.checked = !!resp.checked;
                    rWrapper.appendChild(checkbox);

                    var rTextarea = document.createElement("textarea");
                    rTextarea.style.width = "100%";
                    rWrapper.appendChild(rTextarea);

                    /* DELETE RESPONSE BUTTON */
                    var rDeleteBtn = document.createElement("button");
                    rDeleteBtn.textContent = "🗑";
                    rDeleteBtn.style.cssText = "cursor:pointer; background:none; border:none; color:#c00;";
                    rWrapper.appendChild(rDeleteBtn);

                    rDeleteBtn.onclick = function(){
                        q.responses.splice(rIndex,1);
                        updateNode(n);
                        renderQuestions();
                    };

                    /* CKEditor for response */
                    ClassicEditor.create(rTextarea).then(function(editor){
                        responseEditors.push(editor);
                        editor.model.document.on("change:data", function(){
                            var n2 = ensureData();
                            n2.data[currentLang].questions[qIndex].responses[rIndex].label = editor.getData();
                            updateNode(n2);
                        });
                        editor.setData(resp.label || "");
                    });

                    /* checkbox onchange */
                    checkbox.onchange = function(){
                        var n2 = ensureData();
                        n2.data[currentLang].questions[qIndex].responses[rIndex].checked = checkbox.checked;
                        updateNode(n2);
                    };

                    responsesList.appendChild(rWrapper);
                });
            }

            /* ADD RESPONSE BUTTON */
            var addResponseBtn = document.createElement("button");
            addResponseBtn.textContent = "+ Add Response";
            addResponseBtn.style.cssText = "width:fit-content; padding:4px 8px; cursor:pointer; margin-left:20px;";
            wrapper.appendChild(addResponseBtn);

            addResponseBtn.onclick = function(){
                q.responses.push({label:"", checked:false});
                updateNode(n);
                renderQuestions();
            };

            renderResponses();
        });
    }

    /* ---------------- ADD QUESTION BUTTON ---------------- */
    addQuestionBtn.onclick = function () {
        var n = ensureData();
        n.data[currentLang].questions.push({id:Date.now().toString(), label:"", responses:[]});
        updateNode(n);
        renderQuestions();
    };

    /* ---------------- CKEDITOR INIT ---------------- */
    ClassicEditor.create(titleTextarea).then(function (editor) {
        titleEditor = editor;
        var n = ensureData();
        if (n.data[currentLang].title) editor.setData(n.data[currentLang].title);

        editor.model.document.on("change:data", function () {
            var n2 = ensureData();
            n2.data[currentLang].title = editor.getData();
            updateNode(n2);
        });
    });

    ClassicEditor.create(descTextarea).then(function (editor) {
        descEditor = editor;
        var n = ensureData();
        if (n.data[currentLang].description) editor.setData(n.data[currentLang].description);

        editor.model.document.on("change:data", function () {
            var n2 = ensureData();
            n2.data[currentLang].description = editor.getData();
            updateNode(n2);
        });
    });

    /* ---------------- LANGUAGE SWITCH ---------------- */
    langDiv.querySelectorAll("input[name='lang']").forEach(function (radio) {
        radio.onclick = function () {
            currentLang = radio.value;
            var n = ensureData();

            if (titleEditor) titleEditor.setData(n.data[currentLang].title || "");
            if (descEditor) descEditor.setData(n.data[currentLang].description || "");

            renderQuestions();
        };
    });

    renderQuestions();

    /* ---------------- OPEN MODAL ---------------- */
    modalManager.open({
        id: "form-editor",
        title: "Edit Form",
        content: container,
        width: "900px",
        height: "700px",
        nodeId: nodeId,
        onClose: function () {
            if (titleEditor) titleEditor.destroy();
            if (descEditor) descEditor.destroy();
            destroyQuestionEditors();
        }
    });
});

