    ClassicEditor.create(titleTextarea).then(editor => {
        titleEditor = editor;
        var n = ensureData();
        editor.setData(n.data[currentLang].title || "");

        editor.model.document.on("change:data", () => {
            var n = ensureData();
            n.data[currentLang].title = editor.getData();
            saveNode(n);
        });
    });

    /* ---------------- DESCRIPTION ---------------- */
    var descLabel = document.createElement("div");
    descLabel.textContent = "Form Description"; descLabel.style.fontWeight = "600";
