    /* ---------------- DESCRIPTION ---------------- */
    var descLabel = document.createElement("div");
    descLabel.textContent = "Form Description"; descLabel.style.fontWeight = "600";
    container.appendChild(descLabel);

    var descTextarea = document.createElement("textarea");
    container.appendChild(descTextarea);

    ClassicEditor.create(descTextarea).then(editor => {
        descEditor = editor;
        var n = ensureData();
        editor.setData(n.data[currentLang].description || "");

        editor.model.document.on("change:data", () => {
            var n = ensureData();
            n.data[currentLang].description = editor.getData();
            saveNode(n);
        });
    });

    /* ---------------- QUESTIONS ---------------- */
    var questionsLabel = document.createElement("div");
    questionsLabel.textContent = "Form Questions"; questionsLabel.style.fontWeight = "600"; questionsLabel.style.marginTop = "16px";
    container.appendChild(questionsLabel);

    var questionsList = document.createElement("div");
    questionsList.style.cssText = "display:flex; flex-direction:column; gap:12px;";
    container.appendChild(questionsList);

    var addQuestionBtn = document.createElement("button");
    addQuestionBtn.textContent = "+ Add question"; addQuestionBtn.style.cssText = "width:fit-content; padding:6px 12px; cursor:pointer;";
    container.appendChild(addQuestionBtn);

    addQuestionBtn.onclick = function () {
        var n = ensureData();
        var newQuestion = { id: Date.now().toString(), label: "", response: [] };
        n.data[currentLang].questions.push(newQuestion);
        saveNode(n);
        createQuestionEditor(newQuestion);
    };

    /* ---------------- CREATE QUESTION ---------------- */
    function createQuestionEditor(q) {
        var wrapper = document.createElement("div");
        wrapper.style.cssText = "border:1px solid #ddd; padding:8px; border-radius:4px; display:flex; flex-direction:column; gap:6px;";
        questionsList.appendChild(wrapper);

        var header = document.createElement("div"); header.style.cssText = "display:flex; justify-content:space-between; align-items:center;"; wrapper.appendChild(header);

        var headerTitle = document.createElement("div"); headerTitle.textContent = "Question"; headerTitle.style.fontWeight = "600"; header.appendChild(headerTitle);

        var btnContainer = document.createElement("div"); btnContainer.style.cssText = "display:flex; gap:8px;"; header.appendChild(btnContainer);

        // UPPER / LOWER / DELETE
        const upperBtn = document.createElement("button"); upperBtn.textContent = "▲ Upper"; upperBtn.style.cssText = "cursor:pointer;background:none;border:none;color:#000;font-size:14px;"; btnContainer.appendChild(upperBtn);
        const lowerBtn = document.createElement("button"); lowerBtn.textContent = "▼ Lower"; lowerBtn.style.cssText = "cursor:pointer;background:none;border:none;color:#000;font-size:14px;"; btnContainer.appendChild(lowerBtn);
        const deleteBtn = document.createElement("button"); deleteBtn.textContent = "🗑 Delete"; deleteBtn.style.cssText = "cursor:pointer;background:none;border:none;color:#c00;font-size:14px;"; btnContainer.appendChild(deleteBtn);

        var textarea = document.createElement("textarea"); wrapper.appendChild(textarea);

        ClassicEditor.create(textarea).then(editor => {
            questionEditors.push(editor);
            editor.setData(q.label || "");
            editor.model.document.on("change:data", () => {
                var n = ensureData();
                var qIndex = n.data[currentLang].questions.findIndex(qq => qq.id === q.id);
                if(qIndex !== -1){
                    n.data[currentLang].questions[qIndex].label = editor.getData();
                    saveNode(n);
                }
            });
        });

        // RESPONSES CONTAINER + ADD RESPONSE
        var responsesContainer = document.createElement("div"); responsesContainer.style.cssText = "display:flex; flex-direction:column; gap:6px; margin-left:16px;"; wrapper.appendChild(responsesContainer);

        var addRespBtn = document.createElement("button"); addRespBtn.textContent = "+ Add response"; addRespBtn.style.cssText = "width:fit-content;padding:6px 12px;cursor:pointer;"; wrapper.appendChild(addRespBtn);

        addRespBtn.onclick = function () {
            var n = ensureData();
            var qIndex = n.data[currentLang].questions.findIndex(qq => qq.id === q.id);
            if(qIndex === -1) return;
            var newResp = { id: Date.now().toString(), label: "", checked: false };
            n.data[currentLang].questions[qIndex].response.push(newResp);
            saveNode(n);
            createResponseEditor(newResp, q, responsesContainer);
        };

        (q.response || []).forEach(r => createResponseEditor(r, q, responsesContainer));

        // UPPER / LOWER / DELETE Question
        upperBtn.onclick = function() { moveArrayItem(q.id, -1, 'questions', questionsList); };
        lowerBtn.onclick = function() { moveArrayItem(q.id, 1, 'questions', questionsList); };
        deleteBtn.onclick = function() {
            var n = ensureData(); var qIndex = n.data[currentLang].questions.findIndex(qq=>qq.id===q.id); 
            if(qIndex!==-1){ n.data[currentLang].questions.splice(qIndex,1); saveNode(n); questionsList.removeChild(wrapper);}
        };
    }

    /* ---------------- CREATE RESPONSE ---------------- */
    function createResponseEditor(r,q,container){
        var wrapper = document.createElement("div"); wrapper.style.cssText="display:flex;align-items:center;gap:6px;border:1px dashed #ccc;padding:6px;border-radius:4px;"; container.appendChild(wrapper);

        var checkbox = document.createElement("input"); checkbox.type="checkbox"; checkbox.checked=r.checked; wrapper.appendChild(checkbox);
        var input = document.createElement("textarea"); input.value=r.label||""; wrapper.appendChild(input);

        var upperBtn = document.createElement("button"); upperBtn.textContent="▲"; upperBtn.style.cssText="background:none;border:none;cursor:pointer;font-size:12px;"; wrapper.appendChild(upperBtn);
        var lowerBtn = document.createElement("button"); lowerBtn.textContent="▼"; lowerBtn.style.cssText="background:none;border:none;cursor:pointer;font-size:12px;"; wrapper.appendChild(lowerBtn);

        var deleteBtn = document.createElement("button"); deleteBtn.textContent="🗑"; deleteBtn.style.cssText="background:none;border:none;cursor:pointer;color:#c00;"; wrapper.appendChild(deleteBtn);

        // CKEditor
        ClassicEditor.create(input).then(editor=>{
            questionEditors.push(editor);
            editor.setData(r.label||"");
            editor.model.document.on("change:data",()=>{
                var n=ensureData(); var qIndex=n.data[currentLang].questions.findIndex(qq=>qq.id===q.id);
                if(qIndex===-1) return; var rIndex=n.data[currentLang].questions[qIndex].response.findIndex(rr=>rr.id===r.id);
                if(rIndex!==-1){ n.data[currentLang].questions[qIndex].response[rIndex].label=editor.getData(); saveNode(n);}
            });
        });

        checkbox.onchange=function(){ var n=ensureData(); var qIndex=n.data[currentLang].questions.findIndex(qq=>qq.id===q.id); if(qIndex===-1) return;
            var rIndex=n.data[currentLang].questions[qIndex].response.findIndex(rr=>rr.id===r.id); if(rIndex!==-1){ n.data[currentLang].questions[qIndex].response[rIndex].checked=checkbox.checked; saveNode(n);}
        };

        deleteBtn.onclick=function(){ var n=ensureData(); var qIndex=n.data[currentLang].questions.findIndex(qq=>qq.id===q.id); if(qIndex===-1) return;
            var rIndex=n.data[currentLang].questions[qIndex].response.findIndex(rr=>rr.id===r.id); if(rIndex!==-1){ n.data[currentLang].questions[qIndex].response.splice(rIndex,1); saveNode(n); container.removeChild(wrapper);}
        };

        upperBtn.onclick=function(){ moveArrayItem(r.id,-1,'response',container,q); };
        lowerBtn.onclick=function(){ moveArrayItem(r.id,1,'response',container,q); };
    }

    /* ---------------- UTILS ---------------- */
    function moveArrayItem(itemId, delta, arrayKey, container, parentQ=null){
        var n=ensureData(); 
        var array = parentQ ? n.data[currentLang].questions.find(qq=>qq.id===parentQ.id)[arrayKey] : n.data[currentLang][arrayKey];
        var index=array.findIndex(el=>el.id===itemId);
        if(index===-1) return;
        var newIndex=index+delta; if(newIndex<0 || newIndex>=array.length) return;
        [array[index], array[newIndex]]=[array[newIndex], array[index]];
        var children=container.children; container.insertBefore(children[index],children[newIndex]);
        saveNode(n);
    }

    /* ---------------- PROCESS ---------------- */
    ensureData().data[currentLang].questions.forEach(q=>createQuestionEditor(q));

    /* ---------------- OPEN MODAL ---------------- */
    modalManager.open({
        id:"form-editor",
        title:"Edit Form",
        content:container,
        width:"800px",
        height:"650px",
        nodeId:nodeId,
        onClose:()=>{
            if(titleEditor) titleEditor.destroy();
            if(descEditor) descEditor.destroy();
            destroyQuestionEditors();
        }
    });
});

