//===================================================

// ----------------------- UTILITY FUNCTIONS -----------------------

function flattenStrings(arr) {
  let result = [];
  for (const el of arr) {
    if (typeof el === "string") {
      result.push(el);
    } else if (Array.isArray(el)) {
      result = result.concat(flattenStrings(el));
    }
  }
  return result;
}

