//make a deepcopy of an object
function deepCopy(obj) {
  if (obj === null || typeof obj !== 'object') {
    return obj;
  }
  if (Array.isArray(obj)) {
    return obj.map(item => deepCopy(item));
  }
  const copy = {};
  for (const key in obj) {
    if (obj.hasOwnProperty(key)) {
      copy[key] = deepCopy(obj[key]);
    }
  }
  return copy;
}

//set the "portal" between 2 not directly linked node (add an edge and delete it)
async function portal(id, obj) {

    //get the nodes to link
    const source = node;
    const targets = Array.from(nodeMap.entries()).filter(([key, value]) => value.data?.id === id && key !== node._key);

    //if there is no target
    if (targets.length === 0) {
        console.log("[ERROR] No Portal Found");
        return ["<p></p>", obj["sectionindex"]];
    }

    //if there is more than 1 target found
    if (targets.length > 1) {
        console.log("[ERROR] More than one portal linked on this id");
        return ["<p></p>", obj["sectionindex"]];
    }

    const [targetKey, targetNode] = targets[0];
    console.log(`Portal ${id}: trying to connect ${source._key} to ${targetKey}`);

    try {
      //make a temporary virtual edge
      const virtualEdge = {
        source: source._key,
        target: targetKey,
        sourceHandle: "virtual",
        targetHandle: "0"
      };

      //Retrieves or creates the list of edges for this source node
      const edgeKey = `source-${source._key}`;
      const existingEdges = edgeMap.get(edgeKey) || [];

      // Temporarily adds the virtual edge
      edgeMap.set(edgeKey, [...existingEdges, virtualEdge]);

      //Use next to go through the portal
      const results = await next("virtual", deepCopy(obj));

      // Cleans the virtual edge
      edgeMap.set(edgeKey, existingEdges);

      return results.length > 0 ? results[0] : ["<p></p>", obj["sectionindex"]];
    }
    catch(error) {
      console.log("[ERROR] No link was established with the receiver portal");
      return ["<p></p>", obj["sectionindex"]];
    }
}


