      result = result.concat(flattenStrings(el));
    }
  }
  return result;
}

//This function extracts the modifiers from the first character of args 
//(<p>, <h1>, etc.) and returns them.
function parseModificator(type, args) {
  const type_after = type.slice(0, 1) + "/" + type.slice(1);
  let before = args.split(type).slice(1);
  let after = before.map(part => part.split(type_after)[0].trim());
  let mod = [];
  for (let uncut of after) {
    if (uncut[0] !== "<") break;
