const config = node.data.driveConfig || {};
const folderId = config.folderId || "root";
const clientId = config.clientId;
const clientSecret = config.clientSecret;
const refreshToken = config.refreshToken;

if (!clientId || !clientSecret || !refreshToken) {
    throw new Error("Drive credentials missing. Double-click node to configure.");
}

log(`Fetching files from Drive folder: ${folderId}`);

try {
    // 2. Refresh du Token Access (OAuth 2.0)
    // Google Drive nécessite un Access Token qui expire, on utilise le Refresh Token pour en obtenir un nouveau
    const tokenResponse = await fetch("https://oauth2.googleapis.com/token", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
            client_id: clientId,
            client_secret: clientSecret,
            refresh_token: refreshToken,
            grant_type: "refresh_token"
        })
    });

    if (!tokenResponse.ok) {
        const errText = await tokenResponse.text();
        throw new Error(`Failed to refresh token: ${tokenResponse.status} - ${errText}`);
    }

    const tokenData = await tokenResponse.json();
    const accessToken = tokenData.access_token;

    log("Access Token refreshed successfully.");

    // 3. Appel API Drive pour lister les fichiers
    // On utilise 'q' pour filtrer : parents dans le dossier spécifié et non trashed
    const driveQuery = `'${folderId}' in parents and trashed = false`;
    const driveApiUrl = `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(driveQuery)}&fields=files(id,name,mimeType,webContentLink,thumbnailLink)`;

    const filesResponse = await fetch(driveApiUrl, {
        method: "GET",
        headers: {
            "Authorization": `Bearer ${accessToken}`
        }
    });

    if (!filesResponse.ok) {
        const errText = await filesResponse.text();
        throw new Error(`Drive API Error: ${filesResponse.status} - ${errText}`);
    }

    const filesData = await filesResponse.json();
    const files = filesData.files || [];

    log(`Found ${files.length} files in Drive.`);

