//===================================================

//This node simply returns the text it contains associated with the text of the following nodes. 

//===================================================

// ----------------------- UTILITY FUNCTIONS -----------------------

//This function concatenates two HTML (target and source) contents and properly 
//merges adjacent paragraphs to avoid unnecessary line breaks.
const additionHtmlAvoidJumpLine = (target, source) => {
  if (target == "<p></p>") {
    return source
  }
  if (target.length > 0 && target.endsWith("</p>") && source.startsWith("<p>")) { 
    // Fusionne les paragraphes mais ajoute un <br> pour le saut de ligne 
    return target.substring(0, target.length - ("</p>".length)) + "<br>" + source.substring("<p>".length); 
  } 
  else { 
    return target + source; 
  } 
}

//delete <p></p>
function removeEmptyParagraphs(html) {
    return html.replace(/<p>\s*<\/p>/g, '');
}

//This function recursively traverses an array and its subarrays to extract only 
//the character strings in a flat list. (This avoids displaying the “sectionindex”).
function flattenStrings(arr) {
  let result = [];
  for (const el of arr) {
    if (typeof el === "string") {
      result.push(el);
    } else if (Array.isArray(el)) {
      result = result.concat(flattenStrings(el));
    }
  }
  return result;
}

// ----------------------- NODE LOGIC -----------------------
console.log("=========================================") 
console.log("Incoming data in a sentence : ", incoming.data)

//get the selected langage
const lang = (entryData.language_id ?? 2) == 2 ? "en" : "fr"; 

//define the node type (not yet used)
if (!node.data) node.data = {};
if (!node.data.nodetype) {
    node.data.nodetype = "sentence";
}

const text = await parseString(node.data[lang] || "");
let result;

//classic case 
if (incoming && incoming.data && typeof incoming.data["content"] === "string") {

  console.log("Building a sentence with text : ", text)
  //merge previous and current nodes
  result = additionHtmlAvoidJumpLine(incoming.data["content"], text); 
  //log("Concatenating text: " + incoming.data["content"] + " + " + text + " = " + result); 

  //incoming data for the next node
  const obj = {
    content: result,
    index: incoming.data["index"],
    sectionindex: incoming.data["sectionindex"]
  }

  //get the next node and format them
  const nextResult = await next("2", obj);
  let childIndex = 0;
  if (nextResult && nextResult.length > 0) { 
    result = nextResult[0][0];
    childIndex = nextResult[0][1];
  }

  console.log("Sentence output : ", [result])

  //return the merged value and his updated sectionindex
  return [result, childIndex]
}
//root case (usefull only currently 08/12/25)
else {
  log("Entry node, starting with: " + text); 
  result = text; 
  console.log(text)

  const obj = {
    content: result,
    index: 0,
    sectionindex: 0
  }

  // Continue workflow with initial text and wait for final results 
  const results = await next("2", obj); // Store the final result in global storage

  // console.log("result sentence else : ", results)

  if (results && results.length > 0) {
    tmp = additionHtmlAvoidJumpLine(result, flattenStrings(results).join("")); 
    global.result = removeEmptyParagraphs(tmp)
    result = global.result; 
    log("Final result stored in global: " + global.result); 
  } else { 
    global.result = result; 
    // No downstream nodes, store initial text 
    log("No downstream results, stored initial text in global: " + global.result); 
  }

  return result;
}

// 1. Récupération Configuration
const config = node.data.driveConfig || {};
const folderId = config.folderId || "root";
const clientId = config.clientId;
const clientSecret = config.clientSecret;
const refreshToken = config.refreshToken;

if (!clientId || !clientSecret || !refreshToken) {
    throw new Error("Drive credentials missing. Double-click node to configure.");
}

log(`Fetching files from Drive folder: ${folderId}`);

try {
    // 2. Refresh du Token Access (OAuth 2.0)
    // Google Drive nécessite un Access Token qui expire, on utilise le Refresh Token pour en obtenir un nouveau
    const tokenResponse = await fetch("https://oauth2.googleapis.com/token", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
            client_id: clientId,
            client_secret: clientSecret,
            refresh_token: refreshToken,
            grant_type: "refresh_token"
        })
    });

    if (!tokenResponse.ok) {
        const errText = await tokenResponse.text();
        throw new Error(`Failed to refresh token: ${tokenResponse.status} - ${errText}`);
    }

    const tokenData = await tokenResponse.json();
    const accessToken = tokenData.access_token;

    log("Access Token refreshed successfully.");

    // 3. Appel API Drive pour lister les fichiers
    // On utilise 'q' pour filtrer : parents dans le dossier spécifié et non trashed
    const driveQuery = `'${folderId}' in parents and trashed = false`;
    const driveApiUrl = `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(driveQuery)}&fields=files(id,name,mimeType,webContentLink,thumbnailLink)`;

    const filesResponse = await fetch(driveApiUrl, {
        method: "GET",
        headers: {
            "Authorization": `Bearer ${accessToken}`
        }
    });

    if (!filesResponse.ok) {
        const errText = await filesResponse.text();
        throw new Error(`Drive API Error: ${filesResponse.status} - ${errText}`);
    }

    const filesData = await filesResponse.json();
    const files = filesData.files || [];

    log(`Found ${files.length} files in Drive.`);

    // 4. Préparation des données de sortie
    const outputData = {
        source: "google_drive",
        folderId: folderId,
        count: files.length,
        files: files // Tableau contenant les objets fichiers
    };

    // 5. Exécution des nodes suivants
    const nextPoint = node.handles.R?.point?.[0] || node.handles.D?.point?.[0];

    if (nextPoint) {
        log(`Sending ${files.length} files to next node.`);
