        // Si c'est le node d'entrée, on stocke le résultat
        if (!incoming) {
            const finalResult = results.length > 0 ? results[0] : outputData;
            global.result = finalResult;
            log("Entry node: Stored final Drive result in global.");
        }
        return results.length > 0 ? results[0] : outputData;
    } else {
        return outputData;
    }

} catch (error) {
    log(`Error in Drive Node: ${error.message}`);
    const errorPoint = node.handles.E?.point?.[0];
    if (errorPoint) {
        return await next(errorPoint.id, { error: error.message });
    }
    throw error;
}

