function parseModificator(type, args) {
    type_after = type.slice(0, 1) + "/" + type.slice(1);

    let before = args.split(type).slice(1);
    let after = before.map(part => part.split(type_after)[0].trim());
    let mod = [];
    for (let uncut of after) {
        if (uncut[0] != '<') {
          break
        }
        let cuta = uncut.split("<").slice(1);
        for (let cutb of cuta) {
            mod.push(cutb);
            if (cutb[cutb.length - 1] !== '>') {
                break;
            }
        }
    }
    let res = mod.map(part => part.split(">")[0].trim());

    return res;
}

function createText(mods, index, separator) {
    let mod = [];
    for (let i of mods) {
        let toAddBefore = "<" + i + ">";
        let toAddAfter = "</" + i + ">";
        mod.push(toAddBefore);
        mod.push(toAddAfter);
    }

    let res = "";
    let start = 0;
    while (start < mod.length) {
        res += mod[start];
        start += 2;
    }

    res += index;
    res += separator;

    let end = mod.length - 1;
    while (end > 0) {
        res += mod[end];
        end -= 2;
    }

    return res;
}

