// ----------------------- UTILITY FUNCTIONS -----------------------

//This function recursively traverses an array and its subarrays to extract only 
//the character strings in a flat list. (This avoids displaying the “sectionindex”).
function flattenStrings(arr) {
  let result = [];
  for (const el of arr) {
    if (typeof el === "string") {
      result.push(el);
    } else if (Array.isArray(el)) {
      result = result.concat(flattenStrings(el));
    }
  }
  return result;
}

function deepCopy(obj) {
  if (obj === null || typeof obj !== 'object') {
    return obj;
  }
  if (Array.isArray(obj)) {
    return obj.map(item => deepCopy(item));
  }
  const copy = {};
  for (const key in obj) {
    if (obj.hasOwnProperty(key)) {
      copy[key] = deepCopy(obj[key]);
    }
  }
  return copy;
}

async function portal(id, obj) {

    const source = node;

    const targets = Array.from(nodeMap.entries()).filter(([key, value]) => value.data?.id === id && key !== node._key);

    if (targets.length === 0) {
        console.log("[ERROR] No Portal Found");
        return ["<p></p>", obj["sectionindex"]];
    }
    if (targets.length > 1) {
        console.log("[ERROR] More than one portal linked on this id");
        return ["<p></p>", obj["sectionindex"]];
    }

    const [targetKey, targetNode] = targets[0];
    console.log(`Portal ${id}: trying to connect ${source._key} to ${targetKey}`);
    console.log("Target node data:", targetNode.data);
    console.log("Data to send:", obj);

    try {
      // Crée un edge virtuel temporaire
      const virtualEdge = {
        source: source._key,
        target: targetKey,
        sourceHandle: "virtual",
        targetHandle: "0"
      };

      // Récupère ou crée la liste des edges pour ce nœud source
      const edgeKey = `source-${source._key}`;
      const existingEdges = edgeMap.get(edgeKey) || [];

      // Ajoute temporairement l'edge virtuel
      edgeMap.set(edgeKey, [...existingEdges, virtualEdge]);

      // Utilise next pour traverser le portail
      const results = await next("virtual", deepCopy(obj));

      // Nettoie l'edge virtuel
      edgeMap.set(edgeKey, existingEdges);

