console.log("=========================================")
console.log("Incoming data in a section : ", incoming.data)

//get the selected langage
const lang = (entryData.language_id ?? 2) == 2 ? "en" : "fr";

//define the node type (not yet used) 
if (!node.data) node.data = {};
if (!node.data.nodetype) {
    node.data.nodetype = "section"; 
}

//get the section node attributes
const id = generateUniqueId(`sec_${incoming.data.index}_${incoming.data.sectionindex}`);
const number = await parseString(node.data.numbering || "");
const separatorValue = await parseString(node.data.separator || "");
const text = await parseString(node.data[lang] || "");
const opinionValue = node.data.opinion;
const typeValue = await parseString(node.data.type || "");
const paddingLeft = incoming.data["index"] * 15;
const sectionindex = incoming.data["sectionindex"]

console.log("Building a section with text : ", text)

//get the selected index type (1, A, a, i , etc)
let index = "";
if (number === "123") index = String.fromCharCode("1".charCodeAt(0) + sectionindex);
if (number === "abc") index = getAlphabeticPrefix(sectionindex, false);
if (number === "ABC") index = getAlphabeticPrefix(sectionindex, true);
if (number === "bar") index = getRomanPrefix(sectionindex, false);
if (number === "BAR") index =  getRomanPrefix(sectionindex, true);

//get the selected separator type (/, ., ), etc)
//(garage opinion)
let separator = opinionValue ? "--" : separatorValue;

//get the selected mods (<p>, <h1>, etc)
const mods = parseModificator(typeValue, text);

//build the full indexer of the section (<p>A.</p> for example)
const before = createText(mods, index, separator);

//HTML for implementing the expandable block
const parentHtml = `<div 
      id="${id}"
      style="
        border: 1px solid #E0E0E0;
        cursor:pointer;
        backgroundColor='#F5F5F5';
        padding: 5px 0px 5px ${paddingLeft}px;
        margin: -1px;
        display: flex;
        align-items: center;
      "
      onmouseover="if(this.style.backgroundColor !== 'rgb(224, 224, 224)') this.style.backgroundColor='#F5F5F5'"
      onmouseout="if(this.style.backgroundColor !== 'rgb(224, 224, 224)') this.style.backgroundColor=''"
      onclick="
        var suite = document.getElementById('${id}_inside');
        var icon = document.getElementById('icon-${id}');
        if(suite.style.display === 'none' || suite.style.display === '') {
          suite.style.display = 'block';
          icon.style.transform = 'rotate(0deg)';
          this.style.backgroundColor = '#E0E0E0';
        } else {
          suite.style.display = 'none';
          this.style.backgroundColor  = '';
          icon.style.transform = 'rotate(-90deg)';
        }"
    >
      <svg 
        id="icon-${id}"
        style="transition: all ease-in-out 0.3s;transform:rotate(-90deg);width:20px;height:20px;fill:black;margin-right:8px;"
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
      >
        <path d="M12 15.5 6 9.5l1.41-1.42L12 12.67l4.59-4.59L18 9.5z"/>
      </svg>
      ${typeValue}${before}${typeValue.slice(0,1)+"/"+typeValue.slice(1)}&nbsp;${text}
</div>`;

//incoming data for the next node
const obj = {
    content: "<p></p>",
    index: incoming.data["index"] + 1,
    sectionindex: 0,
  }

//get the next node and extract only the html
const childrenHtmlArray = await next("1", obj);
const childrenHtml = childrenHtmlArray && childrenHtmlArray.length > 0 ? flattenStrings(childrenHtmlArray).join("") : "";

//merge section html's value with next node html's value
const result = incoming.data["content"] + parentHtml + `<div id="${id}_inside" style="border-right:1px solid #E0E0E0; border-left:1px solid #E0E0E0; border-bottom:1px solid #E0E0E0; display:none; margin:-1px;">${childrenHtml}</div>`;

//return the merged html and his updated section index (useful with multiplexers)
console.log("Section output : ", [result])
return [result, incoming.data["sectionindex"] + 1];

