//This function concatenates two HTML (target and source) contents and properly 
//merges adjacent paragraphs to avoid unnecessary line breaks.
const additionHtmlAvoidJumpLine = (target, source) => {
  if (!target || target.trim() === "") return source;

  if (target.endsWith("</p>") && source.startsWith("<p>")) {
    return target.slice(0, -"</p>".length) + source.slice("<p>".length);
  }

  return target + source;
};

//This function recursively traverses an array and its subarrays to extract only 
//the character strings in a flat list. (This avoids displaying the “sectionindex”).
function flattenStrings(arr) {
  let result = [];
  for (const el of arr) {
    if (typeof el === "string") {
      result.push(el);
    } else if (Array.isArray(el)) {
      result = result.concat(flattenStrings(el));
    }
  }
  return result;
}

//This function extracts the modifiers from the first character of args 
//(<p>, <h1>, etc.) and returns them.
function parseModificator(type, args) {
  const type_after = type.slice(0, 1) + "/" + type.slice(1);
  let before = args.split(type).slice(1);
  let after = before.map(part => part.split(type_after)[0].trim());
  let mod = [];
  for (let uncut of after) {
    if (uncut[0] !== "<") break;
    let cuta = uncut.split("<").slice(1);
    for (let cutb of cuta) {
      mod.push(cutb);
      if (cutb[cutb.length - 1] !== ">") break;
    }
  }
  return mod.map(part => part.split(">")[0].trim());
}

//This function applies modifiers (mods) to an index associated with a separator.
function createText(mods, index, separator) {
  let mod = [];
  for (let i of mods) {
    mod.push("<" + i + ">");
    mod.push("</" + i + ">");
  }
  let res = "";
  for (let i = 0; i < mod.length; i += 2) res += mod[i];
  res += index + separator;
  for (let i = mod.length - 1; i > 0; i -= 2) res += mod[i];
  return res;
}

// Index for a and A options
function getAlphabeticPrefix(index, maj) {
        index += 1;
        let prefix = '';
        while (index >= 0) {
            prefix = String.fromCharCode((index % 26) + 64) + prefix;
            index = Math.floor(index / 26) - 1;
        }
        if (!maj) {
