//===================================================

//This node has x outputs, each associated with a condition. 
//The first output associated with a true condition will be returned. 
//If no output has a true condition, then the default output will be returned 
//(if there is no default output, undefined will be returned).

//===================================================

// Get data from incoming, or undefined if entry node
const data = incoming ? incoming.data : undefined;

// Flag to track if any condition matched
let executed = false;
let results = [];

// Loop through right (R) points in order
for (const point of node.handles.R?.point || []) {
    const condStr = point.condition || "";
    let isTrue = false;
    try {
        // Safe evaluation with scoped new Function
        isTrue = await parseString("{{"+condStr+"}}");
    } catch (e) {
        log(`Condition evaluation error for ${point.display}: ${e.message}`);
    }
    log(`Condition ${isTrue}for output ${point.display} (${point.id}): ${point.condition}`);
    if (isTrue === "true") {
        console.log("aaaaaaa");
        results = await next(point.id, data);
        executed = true;
        break; // Exit after first match
    }
}

if (!executed) {
    const defaultPoint = node.handles.D?.point?.[0];
    if (defaultPoint) {
        log(`No conditions matched, proceeding to default output ${defaultPoint.display} (${defaultPoint.id})`);
        results = await next(defaultPoint.id, data);
    } else {
        log('No default point defined, returning data');
        return data;
    }
}

// If this is an entry node (no incoming), store the final result in global
if (!incoming) {
    const finalResult = results.length > 0 ? results[0] : data;
    global.result = finalResult;
    log(`Entry node: Stored final result in global: ${JSON.stringify(finalResult)}`);
}

// Return the first downstream result if available, or data
return results.length > 0 ? results[0] : data;

