        if (!("questions" in n.data[currentLang])) n.data[currentLang].questions = [];
        if (!("title" in n.data[currentLang])) n.data[currentLang].title = "";
        if (!("description" in n.data[currentLang])) n.data[currentLang].description = "";
        return n;
    }

