    /* ---------------- CREATE QUESTION ---------------- */
    function createQuestionEditor(q) {
        var wrapper = document.createElement("div");
        wrapper.style.cssText = "border:1px solid #ddd; padding:8px; border-radius:4px; display:flex; flex-direction:column; gap:6px;";
