        var btnContainer = document.createElement("div"); btnContainer.style.cssText = "display:flex; gap:8px;"; header.appendChild(btnContainer);

        // UPPER / LOWER / DELETE
        const upperBtn = document.createElement("button"); upperBtn.textContent = "▲ Upper"; upperBtn.style.cssText = "cursor:pointer;background:none;border:none;color:#000;font-size:14px;"; btnContainer.appendChild(upperBtn);
