    });
}

node.process:
// Récupération de la donnée entrante
const data = incoming ? incoming.data : undefined;
log(`Multiplexer processing sequence with data: ${JSON.stringify(data)}`);

const points = node.handles.R?.point || [];
let allResults = [];

// Exécution SÉQUENTIELLE
// On boucle sur chaque point de sortie configuré
for (const [index, point] of points.entries()) {
    log(`[Sequence ${index + 1}/${points.length}] Triggering output: ${point.display} (${point.id})`);

    try {
        // Le "await" ici est crucial : il attend que TOUTE la branche connectée 
        // à ce point soit terminée avant de passer à l'itération suivante.
        const branchResult = await next(point.id, data);

        // On collecte les résultats si nécessaire (optionnel, dépend de ton usage)
        if (branchResult) {
            allResults.push({ output: point.display, result: branchResult });
        }
    } catch (e) {
        log(`Error executing sequence for output ${point.display}: ${e.message}`);
        // On continue quand même vers le prochain output ? 
        // Si tu veux arrêter en cas d'erreur, ajoute un "break" ou "throw e" ici.
    }
}

log(`Multiplexer sequence completed.`);

// Si c'est un node d'entrée (pas d'incoming), on stocke le résultat
if (!incoming) {
    global.result = data;
}

// Le multiplexer renvoie généralement la donnée passante originale
// pour permettre le chaining si besoin, ou le résultat agrégé.
return data;

